def ink_count(image):
    # count the ink pixels of an image
    count = 0
    i = 0
    while i < 784:
        if image[i] >= 128:
            count = count + 1
        i = i + 1
    return count


def normalise(image):
    # every pixel from 0..255 to 0..1
    result = []
    i = 0
    while i < 784:
        value = image[i] / 255
        result.append(value)
        i = i + 1
    return result


def squared_distance(a, b):
    # how different are two images? sum of the squared differences
    total = 0
    i = 0
    while i < 784:
        d = a[i] - b[i]
        total = total + d * d
        i = i + 1
    return total


def k_nearest(image, train_images, train_labels):
    # 1. the distance to every training image, with its label
    pairs = []
    for t in range(len(train_images)):
        # (copied from squared_distance, to save a function call)
        total = 0
        i = 0
        while i < 784:
            d = image[i] - train_images[t][i]
            total = total + d * d
            i = i + 1
        pairs.append((total, train_labels[t]))

    # 2. sort the pairs by distance, smallest first (bubble sort)
    n = len(pairs)
    a = 0
    while a < n - 1:
        b = 0
        while b < n - 1 - a:
            if pairs[b][0] > pairs[b + 1][0]:
                temp = pairs[b]
                pairs[b] = pairs[b + 1]
                pairs[b + 1] = temp
            b = b + 1
        a = a + 1

    # 3. keep the first 3
    result = []
    j = 0
    while j < 3:
        result.append(pairs[j])
        j = j + 1
    return result


def majority_vote(neighbours):
    # 1. count the votes, in the order of the neighbours
    labels = []
    counts = []
    for i in range(len(neighbours)):
        label = neighbours[i][1]
        found = False
        for j in range(len(labels)):
            if labels[j] == label:
                counts[j] = counts[j] + 1
                found = True
        if found == False:
            labels.append(label)
            counts.append(1)

    # 2. the winner: walk the neighbours closest first and keep a label only if its
    #    count is STRICTLY bigger, so on a tie the closest of the tied labels stays
    best_label = neighbours[0][1]
    best_count = 0
    for i in range(len(neighbours)):
        label = neighbours[i][1]
        for j in range(len(labels)):
            if labels[j] == label:
                if counts[j] > best_count:
                    best_count = counts[j]
                    best_label = labels[j]
    return best_label


def predict(image, train_images, train_labels):
    # read one digit: the 3 nearest training images vote
    neighbours = k_nearest(image, train_images, train_labels)
    answer = majority_vote(neighbours)
    return answer
